'use client'

import { useEffect, useMemo, useState } from 'react'
import jsPDF from 'jspdf'
import { motion, AnimatePresence } from 'framer-motion'
import { Area, AreaChart, Bar, BarChart, CartesianGrid, Cell, Pie, PieChart, ResponsiveContainer, Tooltip, XAxis, YAxis } from 'recharts'
import { AlertTriangle, Anchor, ArrowRight, BarChart3, Bell, Bot, Check, ChevronDown, CircleHelp, ClipboardList, Download, FileText, Gauge, Globe2, LayoutDashboard, Menu, Navigation, PanelLeftClose, Search, Settings2, Ship, SlidersHorizontal, Sparkles, Target, TrendingUp, Waves, X, Zap } from 'lucide-react'
import { freightData, routeRows, vesselRows } from '@/lib/voyageiq-data'
import { ChartContainer, type ChartConfig, ChartTooltip, ChartTooltipContent } from '@/components/ui/chart'
import { Button } from '@/components/ui/button'
import { Badge } from '@/components/ui/badge'
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card'

const chartConfig = { demand: { label: 'Demand', color: 'var(--chart-1)' }, capacity: { label: 'Capacity', color: 'var(--chart-2)' }, rate: { label: 'Rate', color: 'var(--chart-3)' } } satisfies ChartConfig
const pages = [
  ['Command center', LayoutDashboard], ['Voyage planner', Navigation], ['Freight forecast', TrendingUp], ['Vessel intelligence', Ship], ['Risk analysis', AlertTriangle], ['Optimization', BarChart3], ['AI recommendation', Sparkles], ['What-If simulator', SlidersHorizontal], ['Decision history', ClipboardList], ['Reports', FileText], ['Settings', Settings2],
] as const
const forecastWindows = { '7D': freightData.slice(-7), '15D': freightData, '30D': [...freightData, ...freightData.map((d, i) => ({ ...d, month: `W${i + 1}`, demand: d.demand + 8, capacity: d.capacity - 2, rate: d.rate + 12 }))] }
const risks = [{ name: 'Freight rate volatility', value: 78 }, { name: 'Port congestion', value: 65 }, { name: 'Vessel availability', value: 52 }, { name: 'Route / market risk', value: 61 }, { name: 'Delay probability', value: 70 }, { name: 'Idle time', value: 58 }]
const strategies = [{ name: 'BUY NOW', cost: '$1.636M', risk: 'Medium', confidence: 87, tone: 'success' }, { name: 'WAIT', cost: '$1.721M', risk: 'High', confidence: 61, tone: 'warning' }, { name: 'PARTIAL LOCK', cost: '$1.668M', risk: 'Medium-Low', confidence: 79, tone: 'info' }, { name: 'MULTI-VOYAGE CONTRACT', cost: '$1.612M', risk: 'Low', confidence: 83, tone: 'success' }]

type Page = typeof pages[number][0]

function Metric({ label, value, note, icon: Icon, onClick, accent = 'text-primary' }: { label: string; value: string; note: string; icon: typeof Gauge; onClick?: () => void; accent?: string }) { return <button onClick={onClick} className="group text-left"><Card className="h-full border-border/70 bg-card/80 transition-all duration-300 hover:-translate-y-1 hover:border-primary/40 hover:shadow-[0_0_30px_color-mix(in_oklab,var(--primary)_12%,transparent)]"><CardContent className="flex items-start justify-between p-5"><div className="flex flex-col gap-3"><span className="text-[10px] font-semibold uppercase tracking-[0.16em] text-muted-foreground">{label}</span><span className="font-mono text-2xl font-semibold tracking-tight">{value}</span><span className="text-xs text-muted-foreground">{note}</span></div><div className={`flex size-9 items-center justify-center rounded-lg border border-border/70 bg-muted/60 ${accent}`}><Icon size={17} /></div></CardContent></Card></button> }

function Sidebar({ active, onNavigate, open, onClose }: { active: Page; onNavigate: (page: Page) => void; open: boolean; onClose: () => void }) { return <><AnimatePresence>{open && <motion.button initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }} className="fixed inset-0 z-30 bg-background/70 backdrop-blur-sm lg:hidden" onClick={onClose} aria-label="Close menu" />}</AnimatePresence><aside className={`fixed inset-y-0 left-0 z-40 flex w-72 flex-col border-r border-primary/10 bg-[linear-gradient(180deg,#061523,#071d2c)] transition-transform duration-300 lg:sticky lg:top-0 lg:h-screen lg:translate-x-0 ${open ? 'translate-x-0' : '-translate-x-full'}`}><div className="flex h-20 items-center justify-between border-b border-primary/10 px-6"><div className="flex items-center gap-3"><div className="flex size-9 items-center justify-center rounded-xl bg-primary text-primary-foreground shadow-[0_0_22px_color-mix(in_oklab,var(--primary)_35%,transparent)]"><Waves size={19} /></div><div><div className="font-mono text-sm font-bold tracking-tight"><span>FREIGHT</span><span className="text-primary">SENSE</span></div><div className="text-[10px] uppercase tracking-[0.2em] text-muted-foreground">Decision intelligence</div></div></div><Button variant="ghost" size="icon" className="lg:hidden" onClick={onClose} aria-label="Close navigation"><PanelLeftClose /></Button></div><nav className="flex flex-1 flex-col gap-1 overflow-y-auto p-4"><p className="mb-2 px-3 text-[10px] font-semibold uppercase tracking-[0.18em] text-muted-foreground">Command center</p>{pages.map(([label, Icon]) => <button key={label} onClick={() => { onNavigate(label); onClose() }} className={`nav-wave relative flex items-center gap-3 overflow-hidden rounded-lg px-3 py-2.5 text-left text-sm focus-visible:ring-2 focus-visible:ring-primary ${active === label ? 'nav-active text-primary' : 'text-muted-foreground hover:text-foreground'}`}><Icon size={17} /><span>{label}</span>{active === label && <motion.span layoutId="nav-dot" className="ml-auto size-1.5 rounded-full bg-primary shadow-[0_0_12px_var(--primary)]" />}</button>)}</nav><div className="border-t border-primary/10 p-4"><div className="flex items-center gap-3 rounded-lg bg-primary/5 p-3"><div className="flex size-8 items-center justify-center rounded-full bg-primary/15 font-mono text-xs font-bold text-primary">AR</div><div className="min-w-0"><div className="truncate text-xs font-medium">Alex Rivera</div><div className="truncate text-[11px] text-muted-foreground">Chartering desk</div></div><ChevronDown className="ml-auto text-muted-foreground" size={14} /></div></div></aside></> }

function FreightChart({ windowKey, setWindowKey }: { windowKey: keyof typeof forecastWindows; setWindowKey: (key: keyof typeof forecastWindows) => void }) { const data = forecastWindows[windowKey]; return <Card className="border-border/70 bg-card/80"><CardHeader className="flex-row items-start justify-between space-y-0"><div><CardTitle className="text-sm font-medium">Freight rate intelligence</CardTitle><p className="mt-1 text-xs text-muted-foreground">Historical rate, forecast trajectory, and confidence band</p></div><div className="flex rounded-lg border border-border/70 p-1">{(['7D', '15D', '30D'] as const).map((key) => <button key={key} onClick={() => setWindowKey(key)} className={`rounded-md px-2.5 py-1 text-[10px] font-medium ${windowKey === key ? 'bg-primary text-primary-foreground' : 'text-muted-foreground hover:text-foreground'}`}>{key}</button>)}</div></CardHeader><CardContent><div className="mb-4 flex items-center gap-5 text-xs text-muted-foreground"><span className="flex items-center gap-2"><i className="size-2 rounded-full bg-primary" />Historical + forecast</span><span className="ml-auto font-mono text-[11px] text-primary">TREND: ↑ INCREASING</span></div><ChartContainer config={chartConfig} className="h-[290px] w-full"><AreaChart data={data} margin={{ left: -20, right: 8, top: 15, bottom: 0 }}><defs><linearGradient id="rateFill" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stopColor="var(--color-rate)" stopOpacity={0.28} /><stop offset="100%" stopColor="var(--color-rate)" stopOpacity={0} /></linearGradient></defs><CartesianGrid vertical={false} stroke="var(--border)" strokeDasharray="3 3" /><XAxis dataKey="month" tickLine={false} axisLine={false} tick={{ fill: 'var(--muted-foreground)', fontSize: 11 }} /><YAxis tickLine={false} axisLine={false} tick={{ fill: 'var(--muted-foreground)', fontSize: 11 }} /><ChartTooltip content={<ChartTooltipContent />} /><Area type="monotone" dataKey="rate" stroke="var(--color-rate)" strokeWidth={2.5} fill="url(#rateFill)" /></AreaChart></ChartContainer></CardContent></Card> }

function Modal({ title, children, onClose }: { title: string; children: React.ReactNode; onClose: () => void }) { return <div className="fixed inset-0 z-50 flex items-center justify-center bg-background/75 p-4 backdrop-blur-sm"><motion.div initial={{ opacity: 0, y: 18, scale: .98 }} animate={{ opacity: 1, y: 0, scale: 1 }} className="max-h-[90vh] w-full max-w-xl overflow-y-auto rounded-2xl border border-primary/20 bg-card p-6 shadow-2xl"><div className="mb-5 flex items-center justify-between"><h2 className="text-lg font-semibold">{title}</h2><Button variant="ghost" size="icon" onClick={onClose} aria-label="Close dialog"><X /></Button></div>{children}</motion.div></div> }

function Dashboard({ go }: { go: (page: Page) => void }) { const [windowKey, setWindowKey] = useState<keyof typeof forecastWindows>('15D'); const [search, setSearch] = useState(''); const filtered = routeRows.filter((r) => `${r.route} ${r.vessel} ${r.cargo}`.toLowerCase().includes(search.toLowerCase())); return <div className="flex flex-col gap-6 p-5 md:p-8"><div className="flex flex-col justify-between gap-4 sm:flex-row sm:items-end"><div><p className="mb-2 text-xs font-semibold uppercase tracking-[0.18em] text-primary">Operations overview</p><h1 className="text-balance text-2xl font-semibold tracking-tight md:text-3xl">Good morning, Captain.</h1><p className="mt-2 max-w-xl text-sm leading-6 text-muted-foreground">Your maritime decision intelligence at a glance. From freight forecast to charter decision.</p></div><Button onClick={() => go('Voyage planner')} className="w-fit gap-2"><Sparkles size={16} /> Generate optimal charter plan</Button></div><div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-6"><Metric label="Current freight rate" value="$18.42 / MT" note="+4.8% today" icon={TrendingUp} onClick={() => go('Freight forecast')} /><Metric label="Predicted rate" value="$20.15 / MT" note="+9.4% over 15 days" icon={Target} onClick={() => go('Freight forecast')} /><Metric label="Freight risk score" value="68 / 100" note="HIGH RISK" icon={AlertTriangle} accent="text-amber-400" onClick={() => go('Risk analysis')} /><Metric label="Recommended vessel" value="Supramax" note="58,000 DWT · 94% fit" icon={Ship} onClick={() => go('Vessel intelligence')} /><Metric label="Port congestion" value="Moderate" note="Paradip trending upward" icon={Anchor} accent="text-amber-400" onClick={() => go('Risk analysis')} /><Metric label="Charter strategy" value="BUY NOW" note="87% confidence" icon={Zap} onClick={() => go('AI recommendation')} /></div><div className="grid gap-4 xl:grid-cols-[1.45fr_.55fr]"><FreightChart windowKey={windowKey} setWindowKey={setWindowKey} /><Card className="border-border/70 bg-card/80"><CardHeader><CardTitle className="text-sm">AI confidence</CardTitle><p className="text-xs text-muted-foreground">42 market signals analyzed</p></CardHeader><CardContent><div className="flex flex-col items-center"><div className="relative flex size-40 items-center justify-center rounded-full" style={{ background: 'conic-gradient(var(--primary) 0 87%, var(--muted) 87% 100%)' }}><div className="flex size-32 flex-col items-center justify-center rounded-full bg-card"><span className="font-mono text-3xl font-semibold">87%</span><span className="text-[11px] text-muted-foreground">confidence</span></div></div><div className="mt-5 flex w-full flex-col gap-3 border-t border-border/70 pt-4 text-xs"><div className="flex justify-between"><span className="text-muted-foreground">Model precision</span><span className="font-mono">92.4%</span></div><div className="flex justify-between"><span className="text-muted-foreground">Signal coverage</span><span className="font-mono">84.1%</span></div></div></div></CardContent></Card></div><Card className="border-border/70 bg-card/80"><CardHeader className="flex-row items-center justify-between space-y-0"><div><CardTitle className="text-sm">Active route outlook</CardTitle><p className="mt-1 text-xs text-muted-foreground">Click a route to inspect its decision context</p></div><div className="hidden items-center gap-2 rounded-lg border border-border/70 bg-background/30 px-3 py-2 md:flex"><Search size={14} className="text-muted-foreground" /><input value={search} onChange={(e) => setSearch(e.target.value)} placeholder="Search routes..." className="w-40 bg-transparent text-xs outline-none" /></div></CardHeader><CardContent className="px-0 pb-0"><div className="overflow-x-auto"><table className="w-full text-left text-xs"><thead className="border-y border-border/70 bg-muted/30 text-[10px] uppercase tracking-[0.12em] text-muted-foreground"><tr><th className="px-5 py-3">Route</th><th className="px-4 py-3">Vessel</th><th className="px-4 py-3">ETA</th><th className="px-4 py-3">Confidence</th><th className="px-5 py-3 text-right">Status</th></tr></thead><tbody>{filtered.map((row) => <tr key={row.route} onClick={() => go('Risk analysis')} className="cursor-pointer border-b border-border/50 transition-colors hover:bg-primary/5 last:border-0"><td className="px-5 py-3.5"><div className="font-mono font-medium">{row.route}</div><div className="mt-1 text-[11px] text-muted-foreground">{row.cargo}</div></td><td className="px-4 py-3.5 text-muted-foreground">{row.vessel}</td><td className="px-4 py-3.5">{row.eta}<div className="mt-1 text-[11px] text-muted-foreground">{row.days} transit</div></td><td className="px-4 py-3.5"><div className="flex items-center gap-2"><div className="h-1.5 w-16 rounded-full bg-muted"><div className="h-full rounded-full bg-primary" style={{ width: `${row.confidence}%` }} /></div><span className="font-mono text-[11px]">{row.confidence}%</span></div></td><td className="px-5 py-3.5 text-right"><Badge variant="outline" className={row.status === 'At risk' ? 'border-amber-500/30 bg-amber-500/10 text-amber-400' : 'border-primary/30 bg-primary/10 text-primary'}>{row.status}</Badge></td></tr>)}</tbody></table></div></CardContent></Card></div> }

function Planner({ onGenerated }: { onGenerated: () => void }) { const [loading, setLoading] = useState(false); const [step, setStep] = useState(0); const [done, setDone] = useState(false); const steps = ['Analyzing market data', 'Forecasting freight rates', 'Checking vessel-port compatibility', 'Calculating voyage risk', 'Optimizing charter cost', 'Generating AI recommendation']; function generate() { setLoading(true); setDone(false); setStep(0); const id = window.setInterval(() => setStep((v) => { if (v >= steps.length - 1) { window.clearInterval(id); window.setTimeout(() => { setLoading(false); setDone(true); onGenerated() }, 450); return v }; return v + 1 }), 500) } return <div className="flex flex-col gap-6 p-5 md:p-8"><div><p className="mb-2 text-xs font-semibold uppercase tracking-[0.18em] text-primary">Intelligence workflow</p><h1 className="text-2xl font-semibold">Voyage planner</h1><p className="mt-2 text-sm text-muted-foreground">Turn a voyage input into an optimized charter decision.</p></div><div className="grid gap-4 lg:grid-cols-[1fr_.8fr]"><Card className="border-border/70 bg-card/80"><CardHeader><CardTitle className="text-sm">Voyage input</CardTitle></CardHeader><CardContent className="grid gap-4 sm:grid-cols-2">{[['Origin port', 'Indonesia'], ['Destination port', 'Paradip, India'], ['Commodity', 'Thermal Coal'], ['Cargo quantity', '80,000 MT'], ['Delivery date', '28 Oct 2024'], ['Preferred vessel', 'Supramax'], ['Contract duration', 'Short-Term'], ['Market preference', 'Balanced']].map(([label, value]) => <label key={label} className="flex flex-col gap-2 text-xs text-muted-foreground"><span>{label}</span><select defaultValue={value} className="rounded-lg border border-border/70 bg-background/40 px-3 py-2.5 text-sm text-foreground outline-none focus:ring-2 focus:ring-primary">{[value, 'Handysize', 'Panamax', 'Capesize', 'Spot', 'Medium-Term', 'Long-Term', 'Cost Minimization', 'Risk Minimization', 'Flexibility'].map((v) => <option key={v}>{v}</option>)}</select></label>)}<Button onClick={generate} disabled={loading} className="mt-2 gap-2 sm:col-span-2">{loading ? <span className="size-3 animate-spin rounded-full border-2 border-primary-foreground/40 border-t-primary-foreground" /> : <Sparkles size={16} />} Generate optimal charter plan</Button></CardContent></Card><Card className="border-border/70 bg-card/80"><CardHeader><CardTitle className="text-sm">AI charter pipeline</CardTitle></CardHeader><CardContent>{loading ? <div className="flex flex-col gap-4">{steps.map((s, i) => <div key={s} className={`flex items-center gap-3 text-sm ${i <= step ? 'text-foreground' : 'text-muted-foreground/40'}`}><div className={`flex size-7 items-center justify-center rounded-full border ${i < step ? 'border-primary bg-primary text-primary-foreground' : i === step ? 'border-primary text-primary' : 'border-border'}`}>{i < step ? <Check size={14} /> : i + 1}</div>{s}...</div>)}</div> : done ? <div className="flex flex-col gap-4"><Badge className="w-fit bg-emerald-500/15 text-emerald-300">Plan generated</Badge><h3 className="text-xl font-semibold">BUY NOW <span className="font-mono text-primary">87%</span></h3><p className="text-sm leading-6 text-muted-foreground">Rates are expected to increase over the next 15 days while suitable Supramax availability tightens. Locking now reduces exposure.</p><Button variant="outline" onClick={onGenerated} className="w-fit gap-2">View AI recommendation <ArrowRight size={14} /></Button></div> : <div className="flex min-h-56 flex-col items-center justify-center text-center"><Bot className="mb-3 text-primary" size={32} /><p className="text-sm font-medium">Ready to analyze your voyage</p><p className="mt-2 max-w-xs text-xs leading-5 text-muted-foreground">Six AI agents will evaluate rate, vessel, port, risk, cost, and strategy.</p></div>}</CardContent></Card></div></div> }

function OptimizationView({ onModal }: { onModal: (title: string, body: React.ReactNode) => void }) { const costs = [{ label: 'Freight Cost', value: '$1.284M' }, { label: 'Idle Cost', value: '$84K' }, { label: 'Delay Cost', value: '$62K' }, { label: 'Deadheading Cost', value: '$91K' }, { label: 'Risk Penalty', value: '$91K' }]; const options = [{ name: 'BUY NOW', cost: '$1.636M', freight: '$1.31M', idle: '$72K', delay: '$48K', deadhead: '$88K', penalty: '$118K', risk: 'Medium', exposure: 'Low', savings: '$64K', flexibility: 'High', confidence: '87%' }, { name: 'WAIT', cost: '$1.721M', freight: '$1.39M', idle: '$51K', delay: '$96K', deadhead: '$73K', penalty: '$111K', risk: 'High', exposure: 'High', savings: '$0', flexibility: 'High', confidence: '61%' }, { name: 'PARTIAL LOCK', cost: '$1.668M', freight: '$1.34M', idle: '$69K', delay: '$61K', deadhead: '$83K', penalty: '$115K', risk: 'Medium-Low', exposure: 'Medium', savings: '$38K', flexibility: 'Medium', confidence: '79%' }, { name: 'MULTI-VOYAGE CONTRACT', cost: '$1.612M', freight: '$1.26M', idle: '$78K', delay: '$54K', deadhead: '$86K', penalty: '$134K', risk: 'Low', exposure: 'Very low', savings: '$142K', flexibility: 'Medium', confidence: '83%' }]; return <div className="flex flex-col gap-6 p-5 md:p-8"><div><p className="mb-2 text-xs font-semibold uppercase tracking-[0.18em] text-primary">Optimization engine</p><h1 className="text-2xl font-semibold">Optimization</h1><p className="mt-2 text-sm text-muted-foreground">Calculate the best chartering strategy across cost, risk, exposure, and flexibility.</p></div><Card className="border-primary/30 bg-primary/5"><CardHeader><CardTitle className="text-sm">Cost optimization objective</CardTitle></CardHeader><CardContent><div className="flex flex-wrap items-center gap-2 text-sm font-mono">{costs.map((item, i) => <span key={item.label} className="flex items-center gap-2"><span className="rounded-lg border border-border/70 bg-background/30 px-3 py-2">{item.label}<b className="ml-2 text-primary">{item.value}</b></span>{i < costs.length - 1 && <span className="text-primary">+</span>}</span>)}<span className="text-primary">=</span><span className="rounded-lg border border-primary/30 bg-primary/10 px-3 py-2 font-semibold">$1.612M Total Expected Cost</span></div></CardContent></Card><div className="grid gap-4 xl:grid-cols-4">{options.map((option) => <Card key={option.name} className={option.name === 'MULTI-VOYAGE CONTRACT' ? 'border-primary/60 bg-primary/10 shadow-[0_0_32px_color-mix(in_oklab,var(--primary)_14%,transparent)]' : 'border-border/70 bg-card/80'}><CardHeader><div className="flex items-start justify-between gap-3"><CardTitle className="text-sm leading-5">{option.name}</CardTitle>{option.name === 'MULTI-VOYAGE CONTRACT' && <Badge className="shrink-0 bg-primary/15 text-primary">Optimal</Badge>}</div></CardHeader><CardContent className="flex flex-col gap-4"><div><p className="text-xs text-muted-foreground">Expected total cost</p><p className="mt-1 font-mono text-2xl font-semibold">{option.cost}</p></div><div className="grid grid-cols-2 gap-2 text-xs">{[['Freight', option.freight], ['Idle', option.idle], ['Delay', option.delay], ['Deadheading', option.deadhead], ['Risk penalty', option.penalty], ['Savings', option.savings]].map(([label, value]) => <div key={label} className="rounded-lg bg-background/25 p-2"><span className="block text-muted-foreground">{label}</span><span className="font-mono">{value}</span></div>)}</div><div className="flex flex-col gap-2 border-t border-border/60 pt-3 text-xs"><div className="flex justify-between"><span className="text-muted-foreground">Risk level</span><span>{option.risk}</span></div><div className="flex justify-between"><span className="text-muted-foreground">Rate exposure</span><span>{option.exposure}</span></div><div className="flex justify-between"><span className="text-muted-foreground">Flexibility</span><span>{option.flexibility}</span></div><div className="flex justify-between"><span className="text-muted-foreground">Confidence</span><span className="font-mono text-primary">{option.confidence}</span></div></div></CardContent></Card>)}</div><Card className="border-primary/35 bg-primary/5"><CardContent className="flex flex-col gap-4 p-5 md:flex-row md:items-center md:justify-between"><div><Badge className="mb-3 bg-primary/15 text-primary">Optimal strategy</Badge><h2 className="text-2xl font-semibold">MULTI-VOYAGE CONTRACT</h2><p className="mt-2 max-w-2xl text-sm leading-6 text-muted-foreground">The optimization engine selects the lowest expected total cost with low risk and very low rate exposure. The medium flexibility trade-off is acceptable because the contract protects two future voyages from freight volatility.</p></div><Button onClick={() => onModal('Strategy selected', <p className="text-sm leading-6 text-muted-foreground">Multi-voyage contract selected as the active strategy for the AI recommendation layer.</p>)} className="shrink-0">Use optimal strategy <ArrowRight /></Button></CardContent></Card></div> }

function RecommendationView({ onModal }: { onModal: (title: string, body: React.ReactNode) => void }) { const signals = [{ label: 'Market signal', value: 'Freight rates are forecast to rise approximately 9.4% over the next 15 days.', icon: TrendingUp }, { label: 'Vessel signal', value: 'Suitable Supramax availability is tightening, with the recommended vessel at 94% fit.', icon: Ship }, { label: 'Port signal', value: 'Paradip congestion is moderate and trending upward on the active route.', icon: Anchor }, { label: 'Risk signal', value: 'Waiting increases exposure to freight volatility, delay risk, and idle cost.', icon: AlertTriangle }, { label: 'Cost signal', value: 'The optimization engine predicts a $1.612M expected cost for the multi-voyage strategy.', icon: BarChart3 }]; return <div className="flex flex-col gap-6 p-5 md:p-8"><div><p className="mb-2 text-xs font-semibold uppercase tracking-[0.18em] text-primary">Explainable AI analyst</p><h1 className="text-2xl font-semibold">AI recommendation</h1><p className="mt-2 text-sm text-muted-foreground">Why FREIGHTSENSE recommends the selected strategy.</p></div><Card className="border-primary/40 bg-[linear-gradient(135deg,color-mix(in_oklab,var(--primary)_16%,transparent),transparent)]"><CardContent className="flex flex-col gap-6 p-6 lg:flex-row lg:items-center lg:justify-between"><div><Badge className="mb-4 bg-primary/15 text-primary">Your optimal charter decision</Badge><h2 className="text-4xl font-semibold tracking-tight">MULTI-VOYAGE CONTRACT</h2><p className="mt-2 text-sm text-muted-foreground">83% confidence · selected by the optimization engine</p></div><div className="flex size-28 flex-col items-center justify-center rounded-full border-8 border-primary/60 bg-primary/10"><span className="font-mono text-2xl font-semibold text-primary">83%</span><span className="text-[10px] uppercase tracking-wider text-muted-foreground">confidence</span></div></CardContent></Card><div className="grid gap-3 md:grid-cols-5">{signals.map(({ label, value, icon: Icon }, index) => <div key={label} className="relative"><Card className="h-full border-border/70 bg-card/80"><CardContent className="flex h-full flex-col gap-3 p-4"><div className="flex items-center gap-2 text-primary"><Icon size={16} /><span className="text-xs font-semibold uppercase tracking-wider">{label}</span></div><p className="text-sm leading-6 text-muted-foreground">{value}</p></CardContent></Card>{index < signals.length - 1 && <ArrowRight className="absolute -right-3 top-1/2 z-10 hidden -translate-y-1/2 text-primary md:block" size={16} />}</div>)}</div><Card className="border-primary/30 bg-primary/5"><CardContent className="p-6"><p className="mb-3 text-xs font-semibold uppercase tracking-[0.18em] text-primary">AI conclusion</p><p className="max-w-4xl text-lg leading-8">Considering the market trend, vessel availability, port conditions, risk exposure, and optimized cost, FREIGHTSENSE recommends the <strong className="text-primary">MULTI-VOYAGE CONTRACT</strong>.</p><div className="mt-6 flex flex-wrap gap-3"><Button onClick={() => onModal('Recommended strategy accepted', <p className="text-sm leading-6 text-emerald-300">Decision recorded. The charter desk can now execute the selected multi-voyage contract.</p>)}>Accept recommendation</Button><Button variant="outline" onClick={() => onModal('Alternative decision', <p className="text-sm leading-6 text-muted-foreground">BUY NOW remains the higher-flexibility alternative, but carries more rate exposure and a higher expected cost.</p>)}>Review alternative</Button></div></CardContent></Card><div className="grid gap-4 md:grid-cols-2"><Card className="border-border/70 bg-card/80"><CardHeader><CardTitle className="text-sm">Recommended actions</CardTitle></CardHeader><CardContent className="flex flex-col gap-3 text-sm text-muted-foreground"><p>1. Reserve the 58,000 DWT Supramax candidate.</p><p>2. Negotiate a two-voyage rate corridor before availability tightens.</p><p>3. Monitor Paradip congestion every 12 hours.</p></CardContent></Card><Card className="border-border/70 bg-card/80"><CardHeader><CardTitle className="text-sm">Decision provenance</CardTitle></CardHeader><CardContent className="text-sm leading-6 text-muted-foreground">This recommendation consumes Freight Forecast, Vessel Intelligence, Risk Analysis, and the Optimization Engine. It explains the selected strategy without recalculating or duplicating the strategy comparison.</CardContent></Card></div></div> }

function GenericView({ page, go, onModal }: { page: Page; go: (page: Page) => void; onModal: (title: string, body: React.ReactNode) => void }) { const [selected, setSelected] = useState(0); if (page === 'Freight forecast') return <div className="flex flex-col gap-6 p-5 md:p-8"><div><p className="mb-2 text-xs font-semibold uppercase tracking-[0.18em] text-primary">Market intelligence</p><h1 className="text-2xl font-semibold">Freight forecast</h1><p className="mt-2 text-sm text-muted-foreground">15-day freight rate outlook with confidence band.</p></div><FreightChart windowKey="15D" setWindowKey={() => {}} /><Card className="border-border/70 bg-card/80"><CardHeader><CardTitle className="text-sm">Forecast drivers</CardTitle></CardHeader><CardContent className="grid gap-3 md:grid-cols-3">{['Demand acceleration', 'Tightening tonnage', 'Port congestion'].map((x, i) => <div key={x} className="rounded-xl border border-border/70 bg-background/20 p-4"><div className="text-sm font-medium">{x}</div><div className="mt-2 font-mono text-lg text-primary">{[ '+9.4%', '−12%', '+18%' ][i]}</div><p className="mt-1 text-xs text-muted-foreground">Signal contribution</p></div>)}</CardContent></Card></div>;
 if (page === 'Vessel intelligence') return <div className="flex flex-col gap-6 p-5 md:p-8"><div><p className="mb-2 text-xs font-semibold uppercase tracking-[0.18em] text-primary">Compatibility engine</p><h1 className="text-2xl font-semibold">Vessel intelligence</h1><p className="mt-2 text-sm text-muted-foreground">Compare vessel fit against cargo, port, and draft constraints.</p></div><Card className="border-border/70 bg-card/80"><CardContent className="overflow-x-auto p-0"><table className="w-full min-w-[680px] text-left text-sm"><thead className="border-b border-border/70 text-xs uppercase tracking-wider text-muted-foreground"><tr><th className="p-4">Vessel</th><th className="p-4">Type</th><th className="p-4">Cargo fit</th><th className="p-4">Port fit</th><th className="p-4">Overall</th><th className="p-4 text-right">Action</th></tr></thead><tbody>{[['Handysize','72%','96%','81%'],['Supramax','98%','95%','94%'],['Panamax','95%','78%','84%'],['Capesize','40%','42%','41%']].map((r) => <tr key={r[0]} className="border-b border-border/50 last:border-0"><td className="p-4 font-medium">{r[0]}</td><td className="p-4 text-muted-foreground">{r[0]}</td><td className="p-4 font-mono">{r[1]}</td><td className="p-4 font-mono">{r[2]}</td><td className="p-4 font-mono text-primary">{r[3]}</td><td className="p-4 text-right"><Button variant="ghost" size="sm" onClick={() => onModal(`${r[0]} compatibility review`, <p className="text-sm leading-6 text-muted-foreground">Cargo capacity, draft, LOA, beam, handling support, availability, and idle-risk checks all passed for the selected scenario.</p>)}>Review</Button></td></tr>)}</tbody></table></CardContent></Card><Card className="border-primary/25 bg-primary/5"><CardContent className="flex flex-col gap-3 p-5 md:flex-row md:items-center md:justify-between"><div><Badge className="mb-3 bg-primary/15 text-primary">Recommended vessel</Badge><h2 className="text-xl font-semibold">Supramax · 58,000 DWT</h2><p className="mt-1 text-sm text-muted-foreground">94% compatibility · port draft compatible · good current availability</p></div><Button onClick={() => go('AI recommendation')}>Use recommendation <ArrowRight size={14} /></Button></CardContent></Card></div>;
 if (page === 'Risk analysis') return <div className="flex flex-col gap-6 p-5 md:p-8"><div><p className="mb-2 text-xs font-semibold uppercase tracking-[0.18em] text-primary">Risk intelligence</p><h1 className="text-2xl font-semibold">Risk analysis</h1><p className="mt-2 text-sm text-muted-foreground">Scenario-aware risk drivers for the active Indonesia → Paradip voyage.</p></div><div className="grid gap-4 lg:grid-cols-[.7fr_1.3fr]"><Card className="border-border/70 bg-card/80"><CardContent className="flex min-h-80 flex-col items-center justify-center p-6"><div className="flex size-44 items-center justify-center rounded-full border-[14px] border-amber-400/80 shadow-[0_0_40px_color-mix(in_oklab,#fbbf24_18%,transparent)]"><div className="text-center"><div className="font-mono text-4xl font-semibold">68</div><div className="text-xs text-amber-300">HIGH RISK</div></div></div><p className="mt-5 text-center text-xs leading-5 text-muted-foreground">Rising freight volatility and port congestion are the primary contributors.</p></CardContent></Card><Card className="border-border/70 bg-card/80"><CardHeader><CardTitle className="text-sm">Risk breakdown</CardTitle></CardHeader><CardContent className="flex flex-col gap-5">{risks.map((r) => <div key={r.name}><div className="mb-2 flex justify-between text-xs"><span>{r.name}</span><span className="font-mono text-muted-foreground">{r.value}</span></div><div className="h-2 rounded-full bg-muted"><motion.div initial={{ width: 0 }} animate={{ width: `${r.value}%` }} className={`h-full rounded-full ${r.value >= 70 ? 'bg-amber-400' : 'bg-primary'}`} /></div></div>)}</CardContent></Card></div></div>;
 if (page === 'Optimization') return <OptimizationView onModal={onModal} />; if (page === 'AI recommendation') return <RecommendationView onModal={onModal} />; if (false && (page === 'Optimization' || page === 'AI recommendation')) return <div className="flex flex-col gap-6 p-5 md:p-8"><div><p className="mb-2 text-xs font-semibold uppercase tracking-[0.18em] text-primary">Decision intelligence</p><h1 className="text-2xl font-semibold">{page}</h1><p className="mt-2 text-sm text-muted-foreground">AI converts forecast, vessel fit, risk, and cost into an explainable charter decision.</p></div><Card className="border-primary/30 bg-[linear-gradient(135deg,color-mix(in_oklab,var(--primary)_12%,transparent),transparent)]"><CardContent className="p-6"><div className="flex flex-col gap-6 lg:flex-row lg:items-center lg:justify-between"><div><Badge className="mb-4 bg-emerald-500/15 text-emerald-300">Recommended action</Badge><h2 className="text-4xl font-semibold tracking-tight">BUY NOW</h2><p className="mt-2 text-sm text-muted-foreground">87% decision confidence · expected savings $142,000</p></div><div className="grid grid-cols-2 gap-4 text-sm"><div><div className="text-xs text-muted-foreground">Expected cost</div><div className="mt-1 font-mono text-xl">$1.636M</div></div><div><div className="text-xs text-muted-foreground">Rate increase risk</div><div className="mt-1 font-mono text-xl text-amber-300">+9.4%</div></div></div></div><p className="mt-6 max-w-3xl text-sm leading-6 text-muted-foreground">Freight rates are expected to increase over the next 15 days while suitable vessel availability is tightening. Locking now reduces exposure to further rate increases.</p><div className="mt-6 flex flex-wrap gap-3"><Button onClick={() => onModal('Confirm vessel lock', <div className="flex flex-col gap-4"><p className="text-sm text-muted-foreground">Request a Supramax vessel lock for Indonesia → Paradip at the current modeled exposure?</p><Button onClick={() => onModal('Vessel lock requested', <p className="text-sm text-emerald-300">Vessel Lock Requested. The charter desk has been notified.</p>)}>Confirm lock request</Button></div>)}>Lock vessel now</Button><Button variant="outline" onClick={() => go('Vessel intelligence')}>Compare alternatives</Button><Button variant="outline" onClick={() => go('What-If simulator')}>Run what-if scenario</Button><Button variant="ghost" onClick={() => onModal('Decision report ready', <p className="text-sm text-muted-foreground">Your report has been generated with voyage details, forecast, vessel recommendation, risk, cost, and AI reasoning.</p>)}><Download size={14} /> Export decision report</Button></div></CardContent></Card><div className="grid gap-4 md:grid-cols-5">{[['Freight market','Rates forecast to rise 9.4% over 15 days.'],['Vessel availability','Suitable Supramax tonnage is tightening.'],['Port conditions','Paradip congestion is moderate and trending upward.'],['Cost impact','Waiting increases expected total voyage cost.'],['Risk','Locking now reduces market volatility exposure.']].map(([a,b],i) => <Card key={a} className="border-border/70 bg-card/70"><CardContent className="p-4"><div className="mb-3 flex size-8 items-center justify-center rounded-lg bg-primary/10 text-primary"><Sparkles size={15} /></div><div className="text-sm font-medium">{a}</div><p className="mt-2 text-xs leading-5 text-muted-foreground">{b}</p></CardContent></Card>)}</div><div className="grid gap-4 md:grid-cols-2">{strategies.map((s, i) => <button key={s.name} onClick={() => setSelected(i)} className={`rounded-xl border p-4 text-left transition-all ${selected === i ? 'border-primary bg-primary/10 shadow-[0_0_24px_color-mix(in_oklab,var(--primary)_14%,transparent)]' : 'border-border/70 bg-card/60 hover:border-primary/30'}`}><div className="flex items-center justify-between"><span className="text-sm font-semibold">{s.name}</span>{selected === i && <Check className="text-primary" size={16} />}</div><div className="mt-4 grid grid-cols-3 gap-3 text-xs"><div><div className="text-muted-foreground">Expected cost</div><div className="mt-1 font-mono">{s.cost}</div></div><div><div className="text-muted-foreground">Risk</div><div className="mt-1">{s.risk}</div></div><div><div className="text-muted-foreground">Confidence</div><div className="mt-1 font-mono text-primary">{s.confidence}%</div></div></div></button>)}</div></div>;
 if (page === 'What-If simulator') return <Simulator />; if (page === 'Decision history') return <History onModal={onModal} />; if (page === 'Reports') return <Reports onModal={onModal} />; return <SettingsView /> }

function Simulator() { const [congestion, setCongestion] = useState(50); const [cargo, setCargo] = useState(80); const risk = Math.round(52 + congestion * .3 + (cargo - 80) * .2); const recommendation = congestion > 70 ? 'PARTIAL LOCK' : cargo > 95 ? 'MULTI-VOYAGE CONTRACT' : 'BUY NOW'; return <div className="flex flex-col gap-6 p-5 md:p-8"><div><p className="mb-2 text-xs font-semibold uppercase tracking-[0.18em] text-primary">Decision laboratory</p><h1 className="text-2xl font-semibold">What-If simulator</h1><p className="mt-2 text-sm text-muted-foreground">Change voyage conditions and instantly see how the optimal charter decision changes.</p></div><div className="grid gap-4 lg:grid-cols-[.85fr_1.15fr]"><Card className="border-border/70 bg-card/80"><CardHeader><CardTitle className="text-sm">Modified scenario</CardTitle></CardHeader><CardContent className="flex flex-col gap-6"><label className="text-sm">Cargo quantity <span className="float-right font-mono text-primary">{cargo},000 MT</span><input type="range" min="50" max="120" value={cargo} onChange={(e) => setCargo(Number(e.target.value))} className="mt-3 w-full accent-primary" /></label><label className="text-sm">Port congestion <span className="float-right font-mono text-primary">{congestion}%</span><input type="range" min="10" max="100" value={congestion} onChange={(e) => setCongestion(Number(e.target.value))} className="mt-3 w-full accent-primary" /></label><div className="rounded-xl border border-border/70 bg-background/20 p-4 text-xs text-muted-foreground">Indonesia → Paradip<br />Thermal Coal · Supramax<br />Short-Term · Balanced</div></CardContent></Card><Card className="border-border/70 bg-card/80"><CardHeader><CardTitle className="text-sm">Live decision output</CardTitle></CardHeader><CardContent><div className="mb-6 grid grid-cols-5 gap-2 text-center text-[10px] uppercase tracking-wider text-muted-foreground">{['Forecast','Risk','Vessel','Cost','Recommendation'].map((x) => <div key={x} className="flex flex-col items-center gap-2"><div className="flex size-9 items-center justify-center rounded-full border border-primary/40 bg-primary/10 text-primary"><Check size={14} /></div>{x}</div>)}</div><div className="grid gap-3 sm:grid-cols-2">{[['Freight rate', `$${(18.42 + congestion / 100).toFixed(2)} / MT`],['Risk score', `${risk} / 100`],['Compatibility', congestion > 70 ? '82%' : '94%'],['Expected cost', congestion > 70 ? '$1.668M' : '$1.636M']].map(([a,b]) => <div key={a} className="rounded-xl border border-border/70 p-4"><div className="text-xs text-muted-foreground">{a}</div><div className="mt-2 font-mono text-xl">{b}</div></div>)}</div><div className="mt-4 rounded-xl border border-primary/30 bg-primary/10 p-5"><div className="text-xs uppercase tracking-wider text-primary">Live recommendation</div><div className="mt-2 text-2xl font-semibold">{recommendation}</div><p className="mt-2 text-xs leading-5 text-muted-foreground">Recommendation updates as scenario inputs change.</p></div></CardContent></Card></div></div> }

function History({ onModal }: { onModal: (title: string, body: React.ReactNode) => void }) { const rows = [['07 Oct 2024','Indonesia → Paradip','80,000 MT','Supramax','+9.4%','68','BUY NOW','$1.636M'],['04 Oct 2024','Australia → India','60,000 MT','Panamax','−2.1%','71','WAIT','$1.721M'],['29 Sep 2024','Brazil → China','90,000 MT','Capesize','+4.8%','54','PARTIAL LOCK','$1.668M']]; return <div className="flex flex-col gap-6 p-5 md:p-8"><div><p className="mb-2 text-xs font-semibold uppercase tracking-[0.18em] text-primary">Management</p><h1 className="text-2xl font-semibold">Decision history</h1></div><Card className="border-border/70 bg-card/80"><CardContent className="overflow-x-auto p-0"><table className="w-full min-w-[850px] text-left text-xs"><thead className="border-b border-border/70 text-[10px] uppercase tracking-wider text-muted-foreground"><tr>{['Date','Route','Cargo','Vessel','Forecast','Risk','Recommendation','Expected cost'].map(x => <th key={x} className="p-4">{x}</th>)}</tr></thead><tbody>{rows.map(r => <tr key={r[0]} onClick={() => onModal('Decision detail', <div className="grid gap-3 text-sm">{r.map((x, i) => <div key={i} className="flex justify-between border-b border-border/50 pb-2"><span className="text-muted-foreground">{['Date','Route','Cargo','Vessel','Forecast','Risk','Recommendation','Expected cost'][i]}</span><span>{x}</span></div>)}</div>)} className="cursor-pointer border-b border-border/50 hover:bg-primary/5 last:border-0">{r.map((x, i) => <td key={i} className="p-4">{x}</td>)}</tr>)}</tbody></table></CardContent></Card></div> }
function generateVoyageDecisionPdf() {
  const pdf = new jsPDF({ unit: 'mm', format: 'a4' })
  const pageWidth = pdf.internal.pageSize.getWidth()
  const pageHeight = pdf.internal.pageSize.getHeight()
  const margin = 16
  let y = 24
  const navy: [number, number, number] = [3, 24, 42]
  const ocean: [number, number, number] = [8, 126, 165]
  const ink: [number, number, number] = [27, 43, 57]
  const muted: [number, number, number] = [90, 108, 122]
  const ensureSpace = (height = 12) => { if (y + height > pageHeight - 18) { pdf.addPage(); y = 22; drawHeader() } }
  const drawHeader = () => { pdf.setFillColor(...navy); pdf.rect(0, 0, pageWidth, 14, 'F'); pdf.setTextColor(255, 255, 255); pdf.setFont('helvetica', 'bold'); pdf.setFontSize(9); pdf.text('FREIGHTSENSE  /  DECISION INTELLIGENCE', margin, 9); pdf.setTextColor(...ink) }
  const section = (title: string) => { ensureSpace(18); pdf.setFillColor(...ocean); pdf.rect(margin, y - 4, 3, 8, 'F'); pdf.setTextColor(...navy); pdf.setFont('helvetica', 'bold'); pdf.setFontSize(12); pdf.text(title, margin + 7, y + 1); y += 10 }
  const line = (label: string, value: string) => { ensureSpace(7); pdf.setFont('helvetica', 'bold'); pdf.setFontSize(8.5); pdf.setTextColor(...muted); pdf.text(label, margin, y); pdf.setFont('helvetica', 'normal'); pdf.setTextColor(...ink); pdf.text(value, margin + 52, y); y += 6 }
  const paragraph = (text: string) => { ensureSpace(18); pdf.setFont('helvetica', 'normal'); pdf.setFontSize(9); pdf.setTextColor(...ink); const lines = pdf.splitTextToSize(text, pageWidth - margin * 2); pdf.text(lines, margin, y); y += lines.length * 4.5 + 4 }
  const table = (headers: string[], rows: string[][]) => { ensureSpace(18); const widths = headers.map((_, i) => i === 0 ? 48 : (pageWidth - margin * 2 - 48) / (headers.length - 1)); pdf.setFillColor(232, 245, 249); pdf.rect(margin, y - 4, pageWidth - margin * 2, 7, 'F'); let x = margin; pdf.setFont('helvetica', 'bold'); pdf.setFontSize(7.5); pdf.setTextColor(...navy); headers.forEach((header, i) => { pdf.text(header, x + 2, y); x += widths[i] }); y += 7; pdf.setFont('helvetica', 'normal'); pdf.setTextColor(...ink); rows.forEach((row) => { ensureSpace(8); x = margin; row.forEach((cell, i) => { pdf.text(String(cell), x + 2, y); x += widths[i] }); pdf.setDrawColor(220, 230, 235); pdf.line(margin, y + 2, pageWidth - margin, y + 2); y += 6 }) }
  const footer = () => { const pages = pdf.getNumberOfPages(); for (let i = 1; i <= pages; i += 1) { pdf.setPage(i); pdf.setDrawColor(210, 225, 232); pdf.line(margin, pageHeight - 13, pageWidth - margin, pageHeight - 13); pdf.setFont('helvetica', 'normal'); pdf.setFontSize(7); pdf.setTextColor(...muted); pdf.text('FREIGHTSENSE Decision Intelligence', margin, pageHeight - 8); pdf.text(`Page ${i} of ${pages}`, pageWidth - margin - 22, pageHeight - 8) } }
  drawHeader(); pdf.setTextColor(...navy); pdf.setFont('helvetica', 'bold'); pdf.setFontSize(22); pdf.text('FREIGHTSENSE — Voyage Decision Report', margin, y); y += 7; pdf.setFont('helvetica', 'normal'); pdf.setFontSize(9); pdf.setTextColor(...muted); pdf.text(`Generated ${new Date().toLocaleDateString('en-GB', { day: '2-digit', month: 'short', year: 'numeric' })} · Indonesia → Paradip`, margin, y); y += 15
  section('1. VOYAGE OVERVIEW'); table(['Field', 'Current scenario'], [['Origin', 'Indonesia'], ['Destination', 'Paradip, India'], ['Commodity', 'Thermal Coal'], ['Cargo quantity', '80,000 MT'], ['Delivery date', '28 Oct 2024'], ['Preferred vessel', 'Supramax'], ['Contract duration', 'Short-Term']])
  section('2. FREIGHT FORECAST'); table(['Metric', 'Value'], [['Current freight rate', '$18.42 / MT'], ['Forecasted freight rate', '$20.15 / MT'], ['7-day outlook', '+4.8%'], ['15-day outlook', '+9.4%'], ['30-day outlook', '+12.7%'], ['Forecast trend', 'Increasing'], ['Confidence range', '82% – 91%']])
  section('3. VESSEL INTELLIGENCE'); table(['Metric', 'Recommended vessel'], [['Recommended vessel', 'Ocean Meridian'], ['Vessel type', 'Supramax'], ['DWT', '58,000'], ['Draft', '12.4 m'], ['LOA', '190 m'], ['Beam', '32.3 m'], ['Cargo fit', '98%'], ['Port fit', '95%'], ['Overall compatibility', '94%']])
  section('4. RISK ANALYSIS'); table(['Risk driver', 'Score / level'], [['Overall risk score', '68 / 100'], ['Risk level', 'HIGH RISK'], ['Freight rate volatility', '78'], ['Port congestion', '65'], ['Vessel availability', '52'], ['Route / market risk', '61'], ['Delay risk', '70'], ['Idle time', '58'], ['Top risk drivers', 'Freight volatility; Paradip congestion']])
  section('5. OPTIMIZATION'); table(['Strategy', 'Expected cost', 'Risk', 'Savings', 'Exposure', 'Flexibility'], [['BUY NOW', '$1.636M', 'Medium', '$64K', 'Low', 'High'], ['WAIT', '$1.721M', 'High', '$0', 'High', 'High'], ['PARTIAL LOCK', '$1.668M', 'Medium-Low', '$38K', 'Medium', 'Medium'], ['MULTI-VOYAGE CONTRACT', '$1.612M', 'Low', '$142K', 'Very low', 'Medium']]); paragraph('OPTIMAL STRATEGY: MULTI-VOYAGE CONTRACT. The optimization engine selects the lowest expected total cost with low risk and very low rate exposure.')
  section('6. AI RECOMMENDATION'); line('Final recommendation', 'MULTI-VOYAGE CONTRACT'); line('Confidence', '83%'); line('Market signal', 'Rates forecast to rise 9.4% over 15 days'); line('Vessel signal', 'Supramax availability tightening; 94% fit'); line('Port signal', 'Paradip congestion moderate and rising'); line('Risk signal', 'Waiting increases volatility and idle exposure'); line('Cost signal', '$1.612M expected cost'); paragraph('AI CONCLUSION: Considering market trend, vessel availability, port conditions, risk exposure, and optimized cost, FREIGHTSENSE recommends the MULTI-VOYAGE CONTRACT.')
  section('7. FINAL DECISION'); paragraph('Recommended action: Reserve the 58,000 DWT Supramax candidate and negotiate a two-voyage rate corridor before availability tightens. Expected cost: $1.612M. Main reason: lowest expected cost with low risk and very low rate exposure. Main risk: Paradip congestion and freight volatility. Confidence: 83%.'); footer(); pdf.save('FREIGHTSENSE_Voyage_Decision_Report.pdf')
}

function Reports({ onModal }: { onModal: (title: string, body: React.ReactNode) => void }) { const [generated, setGenerated] = useState(false); const [notice, setNotice] = useState<string | null>(null); const exportPdf = () => { try { generateVoyageDecisionPdf(); setNotice('Decision report downloaded successfully.'); window.setTimeout(() => setNotice(null), 3200) } catch (error) { console.error('[v0] PDF generation failed', error); setNotice('Unable to generate the PDF. Please try again.'); window.setTimeout(() => setNotice(null), 4200) } }; return <div className="relative flex flex-col gap-6 p-5 md:p-8"><div><p className="mb-2 text-xs font-semibold uppercase tracking-[0.18em] text-primary">Management</p><h1 className="text-2xl font-semibold">Reports</h1><p className="mt-2 text-sm text-muted-foreground">Generate and share explainable voyage decisions.</p></div><Card className="border-border/70 bg-card/80"><CardContent className="flex flex-col gap-5 p-6"><div className="flex items-center gap-4"><div className="flex size-12 items-center justify-center rounded-xl bg-primary/10 text-primary"><FileText /></div><div><h2 className="font-semibold">Voyage Decision Report</h2><p className="text-xs text-muted-foreground">Forecast, vessel, risk, cost, strategy, and AI reasoning.</p></div></div><div className="flex flex-wrap gap-3"><Button onClick={() => { setGenerated(true); window.setTimeout(() => setGenerated(false), 2600) }} className="gap-2">{generated ? <Check size={14} /> : <FileText size={14} />} {generated ? 'Report generated' : 'Generate report'}</Button><Button variant="outline" onClick={exportPdf}><Download size={14} /> Export PDF</Button><Button variant="ghost" onClick={() => onModal('Share decision', <div className="flex flex-col gap-4"><p className="text-sm text-muted-foreground">Copy this decision summary to share with your chartering team.</p><div className="rounded-lg bg-muted p-3 text-xs">BUY NOW · Supramax · 87% confidence · $1.636M expected cost</div><Button onClick={() => navigator.clipboard?.writeText('FREIGHTSENSE decision: BUY NOW, Supramax, 87% confidence, $1.636M expected cost.')}>Copy summary</Button></div>)}>Share decision</Button></div></CardContent></Card>{notice && <div role="status" className={`fixed bottom-5 right-5 z-50 rounded-xl border px-4 py-3 text-sm shadow-2xl ${notice.startsWith('Unable') ? 'border-destructive/40 bg-destructive/10 text-destructive' : 'border-primary/40 bg-primary/10 text-primary'}`}>{notice}</div>}</div> }
function SettingsView() { const [theme, setTheme] = useState(true); const [currency, setCurrency] = useState('USD'); return <div className="flex flex-col gap-6 p-5 md:p-8"><div><p className="mb-2 text-xs font-semibold uppercase tracking-[0.18em] text-primary">System</p><h1 className="text-2xl font-semibold">Settings</h1></div><Card className="max-w-2xl border-border/70 bg-card/80"><CardContent className="flex flex-col gap-6 p-6"><label className="flex items-center justify-between text-sm"><span>Dark ocean theme</span><input type="checkbox" checked={theme} onChange={(e) => setTheme(e.target.checked)} className="size-4 accent-primary" /></label><label className="flex items-center justify-between text-sm"><span>Default currency</span><select value={currency} onChange={(e) => setCurrency(e.target.value)} className="rounded-lg border border-border/70 bg-background px-3 py-2"><option>USD</option><option>EUR</option><option>INR</option></select></label><label className="flex items-center justify-between text-sm"><span>Notify on forecast changes</span><input type="checkbox" defaultChecked className="size-4 accent-primary" /></label><label className="flex items-center justify-between text-sm"><span>Risk preference</span><select className="rounded-lg border border-border/70 bg-background px-3 py-2"><option>Balanced</option><option>Risk minimization</option><option>Cost minimization</option></select></label><p className="text-xs text-muted-foreground">Preferences are applied to the current prototype session. Currency selected: {currency}.</p></CardContent></Card></div> }

export default function FREIGHTSENSEDashboard({ initialPage = 'Command center' }: { initialPage?: Page }) { const [active, setActive] = useState<Page>(initialPage); const [menu, setMenu] = useState(false); useEffect(() => { setActive(initialPage); }, [initialPage]); const [modal, setModal] = useState<{ title: string; body: React.ReactNode } | null>(null); const [notifications, setNotifications] = useState(false); const go = (page: Page) => setActive(page); const title = active; return <div className="min-h-screen bg-background text-foreground"><div className="flex min-h-screen"><Sidebar active={active} onNavigate={go} open={menu} onClose={() => setMenu(false)} /><main className="min-w-0 flex-1"><header className="sticky top-0 z-20 flex h-20 items-center justify-between border-b border-border/70 bg-background/85 px-5 backdrop-blur-xl md:px-8"><div className="flex items-center gap-3"><Button variant="ghost" size="icon" className="lg:hidden" onClick={() => setMenu(true)} aria-label="Open navigation"><Menu /></Button><div><div className="flex items-center gap-2"><span className="text-sm font-medium">{title}</span><Badge variant="outline" className="hidden border-primary/30 bg-primary/10 text-[10px] text-primary sm:inline-flex">LIVE OPS</Badge></div><p className="mt-1 hidden text-xs text-muted-foreground sm:block">Monday, 07 October 2024 <span className="mx-1.5 text-border">/</span> Last sync 4 min ago</p></div></div><div className="flex items-center gap-2"><Button variant="ghost" size="icon" onClick={() => setNotifications((v) => !v)} aria-label="Notifications"><Bell size={17} /></Button><Button variant="ghost" size="icon" onClick={() => setModal({ title: 'FREIGHTSENSE help', body: <p className="text-sm leading-6 text-muted-foreground">Use the command center to monitor rates, then generate a plan to move through forecast, compatibility, risk, optimization, and recommendation.</p> })} aria-label="Help"><CircleHelp size={17} /></Button><button onClick={() => setActive('Settings')} className="flex size-8 items-center justify-center rounded-full bg-primary/15 font-mono text-xs font-bold text-primary">AR</button>{notifications && <div className="absolute right-5 top-16 w-72 rounded-xl border border-primary/20 bg-card p-4 shadow-xl"><div className="flex items-center gap-2 text-sm font-medium"><Bell size={15} className="text-primary" /> 3 operational alerts</div><p className="mt-3 text-xs leading-5 text-muted-foreground">Paradip congestion is trending upward. Suitable Supramax availability tightened by 12%.</p></div>}</div></header>{active === 'Command center' ? <Dashboard go={go} /> : active === 'Voyage planner' ? <Planner onGenerated={() => setActive('AI recommendation')} /> : <GenericView page={active} go={go} onModal={(title, body) => setModal({ title, body })} />}</main></div>{modal && <Modal title={modal.title} onClose={() => setModal(null)}>{modal.body}</Modal>}</div> }
